        Arrays.fill(dist, Long.MAX_VALUE);
        dist[S] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, S});
        boolean[] done = new boolean[V];
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[1];
            if (done[u]) continue;
            done[u] = true;
            if (u == T) break;
            for (int v = 0; v < V; v++) {
                if (v == u || done[v]) continue;
                long nd = cur[0] + w[u][v];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.add(new long[]{nd, v});
                }
            }
        }
        System.out.println(dist[T]);
    }

    static long distPointRect(long px, long py, long x1, long y1, long x2, long y2) {
        long dx = 0, dy = 0;
        if (px < x1) dx = x1 - px; else if (px > x2) dx = px - x2;
        if (py < y1) dy = y1 - py; else if (py > y2) dy = py - y2;
        return dx + dy;
    }

    static long rectDist(long ax1, long ay1, long ax2, long ay2, long bx1, long by1, long bx2, long by2) {
        long dx = Math.max(0, Math.max(ax1 - bx2, bx1 - ax2));
        long dy = Math.max(0, Math.max(ay1 - by2, by1 - ay2));
        return dx + dy;
    }
}
